<script lang="ts">
  import { ArrowRight, Search } from '@lucide/svelte';
  export let sites:any[]; export let subjects:any[]; export let dimensions:any[]; export let onSelectSite:(id:string)=>void;
  let view='Sites'; let metric='Impact'; let search=''; let layout='Chart'; let selectedSite: any = null;
  let showEvidence=false;
  const views=['Sites','Countries','Subjects','Data sources','Vendors','Issue categories'];
  const metrics=['Impact','Probability','Open items'];
  $: filtered=sites.filter(s=>`${s.code} ${s.name} ${s.city} ${s.country}`.toLowerCase().includes(search.toLowerCase()));
  $: ordered=[...filtered].sort((a,b)=>metric==='Impact'?b.maxDelayDays-a.maxDelayDays:metric==='Probability'?b.riskProbability-a.riskProbability:b.openItems-a.openItems);
  $: countries=Array.from(new Set(sites.map(s=>s.country))).map(country=>({country,sites:sites.filter(s=>s.country===country)}));
  const vendors=[{name:'LabCorp',description:'ctDNA transfer · 4 days overdue',site:'104',impact:'1.8 days'},{name:'BioClinica',description:'Imaging adjudication',site:'317',impact:'0.9 days'},{name:'Eurofins',description:'Chemistry batch under review',site:'405',impact:'0.4 days'}];
  function value(s:any) { return metric==='Impact' ? s.maxDelayDays : metric==='Probability' ? s.riskProbability : s.openItems; }
  function width(s:any) { const max=metric==='Impact'?8:metric==='Probability'?100:50; return Math.min(100,value(s)/max*100); }
</script>
<div class="space-y-6"><section class="panel"><p class="eyebrow">FIND THE RIGHT PRIORITY</p><h1 class="page-title">Sites &amp; risks</h1><p class="page-intro">Compare the potential effect on lock with the number of open items. Select a record to explore the evidence.</p><div class="insight-banner"><strong>Why impact matters:</strong> Site 104 has 19 open items and an estimated 5–7 day impact; Site 208 has 41 items but a 1–2 day impact. The most items do not necessarily mean the greatest risk.</div></section>
<div class="workflow-tabs" aria-label="Risk views">{#each views as v}<button class:chosen={view===v} on:click={() => view=v}>{v}</button>{/each}</div>
{#if view==='Sites'}<section class="panel"><div class="section-heading"><div><p class="eyebrow">COMPARE SITES</p><h2>Where should we focus?</h2><p>Bars show the selected metric. Select a site for its underlying issues and subjects.</p></div></div><div class="risk-controls"><div class="workflow-tabs">{#each metrics as m}<button class:chosen={metric===m} on:click={() => metric=m}>{m}</button>{/each}</div><label class="search-box"><Search size={16}/><input placeholder="Search site, city or country" bind:value={search}/></label></div>
<div class="workflow-tabs risk-layout" aria-label="Site display"><button class:chosen={layout==='Chart'} on:click={() => layout='Chart'}>Chart</button><button class:chosen={layout==='Table'} on:click={() => layout='Table'}>Table</button></div>{#if layout==='Chart'}<div class="risk-list">{#each ordered as s}<button class="risk-row" on:click={() => {selectedSite=s; showEvidence=false}}><div class="risk-name"><strong>Site {s.id}</strong><small>{s.city}, {s.country}</small></div><div class="risk-bar-area"><div class="risk-bar-track"><div class:critical={s.priority==='Critical'} class:high={s.priority==='High'} style="width:{width(s)}%"></div></div><small>{s.openItems} open items · {s.riskProbability}% sample risk · {s.forecastImpactDays}</small></div><strong class="risk-value">{metric==='Impact'?s.forecastImpactDays:metric==='Probability'?`${s.riskProbability}%`:s.openItems}</strong><ArrowRight size={16}/></button>{:else}<p class="empty-state">No sites match your search.</p>{/each}</div>{:else}<div class="table-scroll"><table class="action-table"><thead><tr><th>Site</th><th>Open items</th><th>Sample risk</th><th>Estimated impact</th><th>Readiness</th><th></th></tr></thead><tbody>{#each ordered as s}<tr><td><button class="table-action" on:click={() => {selectedSite=s; showEvidence=false}}>Site {s.id}</button><small>{s.city}</small></td><td>{s.openItems}</td><td>{s.riskProbability}%</td><td>{s.forecastImpactDays}</td><td>{s.readinessScore}/100</td><td><button class="text-link" on:click={() => {selectedSite=s; showEvidence=false}}>Explore →</button></td></tr>{/each}</tbody></table></div>{/if}<p class="footnote">Impact uses the upper end of each sample range for the bar length. Percentages are illustrative, not calibrated probabilities.</p></section>
{:else if view==='Countries'}<section class="panel"><h2 class="minor-title">Risk by country</h2><p class="page-intro">Aggregated from the site records available in this demo.</p><div class="risk-list">{#each countries as c}<button class="risk-row" on:click={() => onSelectSite(c.sites[0].id)}><div class="risk-name"><strong>{c.country}</strong><small>{c.sites.length} represented site(s)</small></div><div class="risk-bar-area">{c.sites.reduce((n:number,s:any)=>n+s.openItems,0)} open items · highest risk {Math.max(...c.sites.map((s:any)=>s.riskProbability))}%</div><span>Open site</span><ArrowRight size={16}/></button>{/each}</div></section>
{:else if view==='Subjects'}<section class="panel"><h2 class="minor-title">Subjects requiring review</h2><p class="page-intro">Select a subject's site, then open the subject from its roster.</p><div class="risk-list">{#each subjects as s}<button class="risk-row" on:click={() => onSelectSite(s.siteId)}><div class="risk-name"><strong>{s.id}</strong><small>Site {s.siteId}</small></div><div class="risk-bar-area">{s.riskLevel || 'Review'} · {s.cohort}</div><span>Open site</span><ArrowRight size={16}/></button>{/each}</div></section>
{:else if view==='Data sources' || view==='Issue categories'}<section class="panel"><h2 class="minor-title">{view}</h2><p class="page-intro">Explore the readiness dimension and evidence behind each sample signal.</p><div class="risk-list">{#each dimensions as d}<button class="risk-row" on:click={() => onSelectSite('104')}><div class="risk-name"><strong>{d.name}</strong><small>{d.score}% ready</small></div><div class="risk-bar-area">{d.details}</div><span>Site 104</span><ArrowRight size={16}/></button>{/each}</div><p class="footnote">Example evidence links to Site 104; source-level aggregation is illustrative.</p></section>
{:else}<section class="panel"><h2 class="minor-title">External partners</h2><div class="risk-list">{#each vendors as v}<button class="risk-row" on:click={() => onSelectSite(v.site)}><div class="risk-name"><strong>{v.name}</strong><small>{v.description}</small></div><div class="risk-bar-area">Example estimated impact: {v.impact}</div><span>Site {v.site}</span><ArrowRight size={16}/></button>{/each}</div></section>{/if}
{#if selectedSite}<div class="drawer-overlay"><button class="drawer-backdrop" aria-label="Close site preview" on:click={() => selectedSite=null}></button><aside class="detail-drawer" aria-label="Site preview"><div class="drawer-top"><div><p class="eyebrow">SITE SNAPSHOT</p><h2>Site {selectedSite.id}</h2><p>{selectedSite.name} · {selectedSite.city}</p></div><button class="drawer-close" aria-label="Close site preview" on:click={() => selectedSite=null}>×</button></div><div class="drawer-content"><div class="drawer-metrics"><div><small>READINESS</small><strong>{selectedSite.readinessScore}/100</strong></div><div><small>SAMPLE RISK</small><strong>{selectedSite.riskProbability}%</strong></div><div><small>IMPACT</small><strong>{selectedSite.forecastImpactDays}</strong></div></div><div class="insight-banner"><strong>Why this matters:</strong> {selectedSite.reasons[0]}</div><div class="drawer-section"><h3>What is driving the risk?</h3><p>Illustrative factor contributions for this site.</p>{#each Object.entries(selectedSite.breakdown) as [name, weight]}<div class="factor-row"><div><span>{name.replace(/([A-Z])/g,' $1').replace(/^./, (x:string)=>x.toUpperCase())}</span><strong>{weight}%</strong></div><div class="driver-track"><div style="width:{weight}%"></div></div></div>{/each}</div><button class="subtle-button" on:click={() => showEvidence=!showEvidence}>{showEvidence ? 'Hide supporting details' : 'Show supporting details'}</button>{#if showEvidence}<div class="evidence-list"><h3>Supporting signals</h3>{#each selectedSite.reasons as reason}<p>• {reason}</p>{/each}<small>Source reference: {selectedSite.traceability.sourceSystem}<br/>Example extract: {selectedSite.traceability.extractDate}</small></div>{/if}<div class="button-row"><button class="primary-dark" on:click={() => onSelectSite(selectedSite.id)}>View full site →</button><button class="subtle-button" on:click={() => selectedSite=null}>Back to comparison</button></div><p class="footnote">Illustrative sample data, not a calibrated prediction.</p></div></aside></div>{/if}
</div>
